params.open:
/**
 * Opens a pull request from local changes: creates the branch from the current HEAD, commits and
 * pushes the listed files through delivery.commit, and creates the pull request. Uncommitted
 * changes move to the new branch. When the branch is already checked out, it commits there; when
 * it already has an open pull request, it returns that one instead of creating another.
 *
 * @param input.branch - Branch to create, or the checked-out branch to reuse. Not main or master.
 * @param input.files - Repository-relative files to commit (see delivery.commit).
 * @param input.message - Commit message (see delivery.commit).
 * @param input.title - Pull request title. The default is the commit message's first line.
 * @param input.body - Pull request description. The default is empty.
 * @param input.base - Base branch. The default is main.
 * @param input.draft - Open the pull request as a draft. The default is false.
 */
async function openPullRequest(
  {
    git: { revParse, switchBranch },
    delivery: { commit },
    gh: { prCreate, prList },
  },
  input: {
    branch: string;
    files: string[];
    message: string;
    title?: string;
    body?: string;
    base?: string;
    draft?: boolean;
  },
) {
  const branch = input.branch.trim();
  const base = (input.base ?? "main").trim();
  const validBranch = (name: string) =>
    /^[\w][\w./-]*$/.test(name) && !name.includes("..") && !name.endsWith("/") && !name.endsWith(".lock");
  if (!validBranch(branch)) throw new Error(`branch is not a valid branch name: ${input.branch}`);
  if (!validBranch(base)) throw new Error(`base is not a valid branch name: ${input.base}`);
  if (branch === "main" || branch === "master" || branch === base) {
    throw new Error(`branch must differ from ${branch === base ? "the base branch" : branch}`);
  }
  const title = (input.title ?? input.message.trim().split("\n")[0] ?? "").trim();
  if (title.length === 0) throw new Error("title must not be empty");

  const current = (await revParse(["--abbrev-ref", "HEAD"], { raise: true })).stdout.trim();
  const created = current !== branch;
  if (created) await switchBranch(["-c", branch], { raise: true });
  const committed = await commit({ files: input.files, message: input.message, push: true });

  const listed = await prList({
    head: branch,
    state: "open",
    json: ["number", "url"],
    limit: 1,
    raise: true,
  });
  const existing = (JSON.parse(listed.stdout || "[]") as Array<{ number: number; url: string }>)[0];
  if (existing) {
    return {
      number: existing.number,
      url: existing.url,
      created: false,
      branch,
      branchCreated: created,
      sha: committed.sha,
      files: committed.files,
    };
  }
  const opened = await prCreate({
    title,
    body: input.body ?? "",
    base,
    head: branch,
    ...(input.draft === true ? { draft: true } : {}),
    raise: true,
  });
  const url = opened.stdout.trim().split("\n").at(-1) ?? "";
  const number = Number(url.match(/\/pull\/(\d+)/)?.[1] ?? Number.NaN);
  return {
    number: Number.isInteger(number) ? number : null,
    url,
    created: true,
    branch,
    branchCreated: created,
    sha: committed.sha,
    files: committed.files,
  };
}

params.merge:
/**
 * Merges an open pull request and, with sync, switches to its base branch and fast-forwards it.
 *
 * @param input.number - Pull request number.
 * @param input.method - Merge method: merge, squash, or rebase. Repositories allow different ones.
 * @param input.repo - GitHub owner/name. The default is the current repository. sync updates the
 *   local checkout, so use it only for the current repository.
 * @param input.deleteBranch - Delete the head branch after merging. The default is false.
 * @param input.sync - After merging, run git switch <base> and git pull --ff-only. The default is
 *   false. A failed sync reports the merge as done and names the step that failed.
 */
async function merge(
  { gh: { prView, prMerge }, git: { switchBranch, pull, revParse } },
  input: {
    number: number;
    method: "merge" | "squash" | "rebase";
    repo?: string;
    deleteBranch?: boolean;
    sync?: boolean;
  },
) {
  if (!Number.isInteger(input.number) || input.number < 1) {
    throw new Error("number must be a positive integer");
  }
  if (!["merge", "squash", "rebase"].includes(input.method)) {
    throw new Error("method must be merge, squash, or rebase");
  }
  if (input.repo !== undefined && !/^[\w.-]+\/[\w.-]+$/.test(input.repo)) {
    throw new Error("repo must be owner/name");
  }
  const repo = input.repo ? { repo: input.repo } : {};
  const viewed = await prView(input.number, {
    ...repo,
    json: ["number", "state", "url", "baseRefName", "headRefName"],
    raise: true,
  });
  const pr = JSON.parse(viewed.stdout) as {
    state: string;
    url: string;
    baseRefName: string;
    headRefName: string;
  };
  if (pr.state !== "OPEN") {
    throw new Error(`Pull request #${input.number} is ${pr.state.toLowerCase()}, not open`);
  }
  await prMerge(input.number, {
    ...repo,
    method: input.method,
    ...(input.deleteBranch === true ? { deleteBranch: true } : {}),
    raise: true,
  });
  const merged = {
    number: input.number,
    url: pr.url,
    merged: true,
    method: input.method,
    base: pr.baseRefName,
    head: pr.headRefName,
  };
  if (input.sync !== true) return { ...merged, synced: null };

  // The merge already happened, so a failed sync is reported, not thrown.
  const step = async (name: string, run: () => Promise<{ code: number; stderr: string }>) => {
    const result = await run();
    return result.code === 0
      ? undefined
      : `${name} failed with exit ${result.code}: ${result.stderr.trim().slice(-1000)}`;
  };
  const failure =
    (await step(`git switch ${pr.baseRefName}`, () => switchBranch([pr.baseRefName]))) ??
    (await step("git pull --ff-only", () => pull(["--ff-only"])));
  if (failure) return { ...merged, synced: { ok: false as const, branch: pr.baseRefName, error: failure } };
  const sha = (await revParse(["HEAD"], { raise: true })).stdout.trim();
  return { ...merged, synced: { ok: true as const, branch: pr.baseRefName, sha } };
}
